def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    prev_bids = []
    reqs = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            reqs.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if not alive:
        return max(0.0, min(budget, 5.0))

    total_req = WATER_REQ
    for r in reqs:
        total_req += r

    scarcity = 0.0
    if total_req > 0:
        scarcity = max(0.0, min(1.0, 1.0 - (float(supply) / float(total_req))))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / float(len(prev_bids)) if prev_bids else 0.0

    if hp <= 2 or no_water >= 2:
        target = max(128.0, highest_prev + 1.0)
    elif hp <= 4 or no_water >= 1:
        target = max(95.0, avg_prev * 0.9, highest_prev * 0.82)
    else:
        if supply <= 16:
            target = max(72.0, highest_prev * 0.62, avg_prev * 0.7)
        elif supply >= 22:
            target = max(22.0, highest_prev * 0.22)
        else:
            target = max(38.0, highest_prev * 0.36, avg_prev * 0.32)

    if day >= 8:
        target += 8.0
    if scarcity > 0.55:
        target += 12.0
    elif scarcity > 0.35:
        target += 6.0

    if budget < target:
        if hp <= 3 or no_water >= 1:
            target = budget
        else:
            target = min(budget, max(0.0, budget * 0.55))

    if hp >= 7 and no_water == 0 and supply >= 21:
        target = min(target, 35.0)

    bid = max(0.0, min(budget, target))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    supply = day_context['supply']
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # Determine competitive baseline based on supply
    # If supply is tight, bid higher to ensure allocation
    if supply < 18:
        base_bid = DAILY_SALARY * 0.9
    else:
        base_bid = DAILY_SALARY * 0.6

    # Look at yesterday's behavior
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        # If opponents are bidding aggressively, match or slightly exceed if HP is low
        if my_status['hp'] <= 3:
            return min(my_status['budget'], max(base_bid, max_prev + 5.0))
        # Otherwise, bid conservatively to save budget
        return min(my_status['budget'], max(base_bid, max_prev * 0.95))

    return min(my_status['budget'], base_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.6)
    prev_bids = [o.get('previous_trace', {}).get('bid', 0) for o in alive if o.get('previous_trace')]
    highest_prev = max(prev_bids) if prev_bids else 0
    hp = my_status['hp']
    budget = my_status['budget']
    if hp <= 2:
        bid = min(budget, max(DAILY_SALARY * 0.9, highest_prev + 1))
    elif hp <= 4:
        bid = min(budget, max(DAILY_SALARY * 0.7, highest_prev + 0.5))
    else:
        bid = min(budget, DAILY_SALARY * 0.6)
    return round(bid, 1)
